update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p016","body":"کون اپنا ہے کون اپنا نہیں\nیہ سیدھی بات میں سمجھا نہیں\n\nتم نے چنا ، تم نے چاہا\nتم ہی کو میں بھایا نہیں\n\nایک خواب سے نیند ایسی کھلی\nپھر کوئی دوسرا دیکھا نہیں\n\nڈھونڈو گے تو ملوں گا وہاں\nجہاں بشر نہیں کوئی سایہ نہیں\n\nجن کی  فطرت تھی اڑنے کی\nوہ ایسے ڈوبے کہ کنارہ نہیں\n\nضبط کا کھیل بھی ایسا ہے\nجو کھیلا نہیں وہ ہارا نہیں\n\nزندگی جس تسلسل سے ہے\nاس میں ایک ٹھکانہ نہیں\n\nچھوڑوگلے شکوے، لوٹ آؤ\nاحمد ؔ اب اتنا بھی برا نہیں"},{"slug":"tum-p017","body":"ابھی ، اس پل یونہی عادتاً\nچند فٹ کی اندھیر نگری میں\nسانس بھی سنائی دیتا ہے\nاور بلا کی اداسی ہے\nفضا بھی ہے دھواں دھواں\nگھاؤ بھی سب ہرے بھرے\nایک داغ ابھی نیا ہے شاید\nاور تنگ تنگ ہوا سی ہے\nدیکھو میری دنیا میں\nچند سوچے ہیں اور میں\nکاغذ ہے اپنی قسمت کا\nدرد و الم کی سیاہی ہے\nایک گھر ہے اور دفتر\nلوگ ہیں پر تھوڑے بہت\nکچھ سے اچھا ملنا ہے\nاور باقی تو بس بےحسی ہے\nسو گھر کے ایک کمرے میں\nیونہی بےسبب پڑا ہوں عادتاً\nسانس بھی سنائی دیتا ہے\nاور بلا کی اداسی ہے"},{"slug":"tum-p018","body":"دن گزرا رات گزاری\nپر کسی کو یاد نہ کیا\nیوں بھی گزرا ہجر کا عالم\nنہ ہوش سنبھلی ، نہ دیپ جلا\n\nچلی بادِ صبا تو دھیان پڑا\nایک کسی کی ہوا تھے ہم\nایسا نہیں کہ بےوفا ہوئے\nیہ بھی نہیں کہ باوفا تھے ہم\n\nہم نہ عاشق نہ ہی رقیب ٹھہرے\nاتنی مخلصی کہ بدنصیب ٹھہرے\nبھولا سا ایک پرانا قصہ جیسے\nکبھی اجنبی کبھی قریب ٹھہرے\n\nتم کو چاہا ، اتنا چاہا کہ بس\nخود کی حالت بھول گئے\nزندگی کی پھر ایسی چلی\nوہ بےفکریاں ، وہ اصول گئے\n\nکبھی وقت نکالا اور خوب سوچا\nکبھی وقت ملا مگر یاد نہیں\nبس ایک شے قائم دائم ہے\nاحمد تم بن اب اتنا شاد نہیں"},{"slug":"tum-p019","body":"نیم مسرت چہرے مردہ دلوں کی بات ہے\nہم کو لگا تھا محبت چند دنوں کی بات ہے\n\nجاڑوں کی بات ہے ، پھول کھلتے ہیں\nپھول کھلتے ہیں ، اجاڑوں کی بات ہے\n\nوہ لوٹ آئے گا ، وہ لوٹے گا ، وہ لوٹتا ہوگا\nغلط سمجھے تھے صحیح دنوں کی بات ہے\n\nکل شب فلک پہ نہ مہتاب تھا، نہ شفق ،نہ ستارہ\nیقیناً یہ ٹوٹے ہوئے شہابوں کی بات ہے\n\nرنج تو سراسر سفرِِ زندگی ہے\nاور خوشی تو منزلوں کی بات ہے\n\nاحمد  دیکھا ہے اکثر خوابوں کو حقیقت ہوتے\nپھر بھی لگتا ہے یہ بس افسانوں کی بات ہے"},{"slug":"tum-p020","body":"اے اداس نگر کے مکیں  دل\nاس قدر کیوں افسردہ ہے تو\nکس راہ ہے سفر، کون ہمراہِ سفر\nکس منزل کا آخر پیشوا ہے تو\n\nاے میرے گمنام ، بےآرزو ، میرے گمشدہ دل\nتو ہے ساحل کنارے اور زندگی موج میں ہے\nاور سوال یہ ہر لہر تجھ سے پوچھ رہی ہے\nتری تلاش ہے کیا، کون تری کھوج میں ہے\n\nاے دل کہ اس انگنت ستاروں کے جال تلے\nکوئی نہیں جو تیری آرزوؤں کا پاس رکھے\nکوئی نہیں جو حسرتوں میں تیری حسرت رکھتا ہو\nکوئی نہیں جو اس دور میں تجھے خاص رکھے\n\nتو جستجو چھوڑ خود کو مت توڑ ، جانے دے\nخوابوں کی دنیا کو اب حقیقت کے افسانے دے\nچھوڑ بھی اب مسافروں کا حساب کتاب احمد\nجو تیری وسعتوں میں آئے جائے ، آنے جانے دے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
